"""Vector equation widget: the SVGs generated by ``tools/render_equations.py``, recoloured from the theme.

Used by Analysis (Model details); formerly part of the Calculation details panel.

An equation is one SVG (``<key>.svg``) or, for a model with several statements, one SVG per statement
(``<key>_1.svg``, ``<key>_2.svg``, ...) stacked here, left-aligned (2026-10-28: display-style fractions are tall, and
matplotlib's multi-line math overlapped them).  The equation is drawn at its design size; a column narrower than that
scales it down - but never below ``MIN_SCALE`` of the design size, so fractions and scripts stay readable (a narrower
column clips the right end rather than shrinking the whole equation into illegibility; the layouts give the
equation region enough width at every size class).
"""

from __future__ import annotations

from pathlib import Path

from PySide6.QtCore import QByteArray, QRectF, QSize
from PySide6.QtGui import QPainter
from PySide6.QtSvg import QSvgRenderer
from PySide6.QtWidgets import QSizePolicy, QWidget

from ..theme import THEME, t

EQ_DIR = Path(__file__).resolve().parents[1] / "equations"
LINE_GAP = 8            # px between stacked statements (at scale 1)
MIN_SCALE = 0.85        # of the design size: the smallest an equation is ever drawn

_SVG_SRC: dict[str, str] = {}


def _svg_source(name: str) -> str:
    """Read an equation SVG once.  The files never change, only the recolouring does, and a
    theme switch was re-reading them from disk each time."""
    src = _SVG_SRC.get(name)
    if src is None:
        path = EQ_DIR / f"{name}.svg"
        src = path.read_text(encoding="utf-8") if path.exists() else ""
        _SVG_SRC[name] = src
    return src


def part_names(key: str) -> list[str]:
    """``[key]`` for a one-statement equation, else ``[key_1, key_2, ...]`` (in order)."""
    if (EQ_DIR / f"{key}.svg").exists():
        return [key]
    parts = []
    i = 1
    while (EQ_DIR / f"{key}_{i}.svg").exists():
        parts.append(f"{key}_{i}")
        i += 1
    return parts


class Equation(QWidget):
    """Vector equation (SVGs generated by tools/render_equations.py), recoloured to text-primary."""

    def __init__(self, key: str, scale: float = 1.0, parent=None):
        super().__init__(parent)
        self.key = key
        self.parts = part_names(key)
        self._srcs = [_svg_source(n) for n in self.parts]
        self._renderers: list[QSvgRenderer] = []
        self.scale = scale
        self._load()
        THEME.changed.connect(self._theme_changed)

    def _theme_changed(self, *_):
        self._load()
        self.update()

    def _load(self):
        self._renderers = []
        sizes = []
        for src in self._srcs:
            if not src:
                continue
            r = QSvgRenderer(QByteArray(src.replace("currentColor", t("text-primary")).encode("utf-8")))
            self._renderers.append(r)
            s = r.defaultSize()
            sizes.append((s.width() * self.scale * 1.1, s.height() * self.scale * 1.1))
        self._sizes = sizes
        if not sizes:
            self.natural = QSize(0, 0)
            return
        w = max(sw for sw, _sh in sizes)
        h = sum(sh for _sw, sh in sizes) + LINE_GAP * self.scale * (len(sizes) - 1)
        self.natural = QSize(int(w + 0.999), int(h + 0.999))
        self.setFixedHeight(self.natural.height())
        self.setMinimumWidth(min(self.natural.width(), int(self.natural.width() * MIN_SCALE)))
        self.setMaximumWidth(self.natural.width())
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def sizeHint(self) -> QSize:
        return getattr(self, "natural", QSize(0, 0))

    def drawn_scale(self) -> float:
        """The scale the equation is drawn at relative to its design size (1, or down to ``MIN_SCALE``)."""
        return max(MIN_SCALE, min(1.0, self.width() / max(1, self.natural.width())))

    def paintEvent(self, _e):
        if not self._renderers:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        k = self.drawn_scale()
        total = self.natural.height() * k
        y = (self.height() - total) / 2
        for r, (sw, sh) in zip(self._renderers, self._sizes):
            r.render(p, QRectF(0, y, sw * k, sh * k))
            y += (sh + LINE_GAP * self.scale) * k
        p.end()
